  -- ── measures ──────────────────────────────────────────────────────────────
  -- H.R. 1 (117th house) — For the People Act of 2021
  SELECT id INTO m_117_h_r_1 FROM vr_measures
   WHERE congress = 117 AND chamber = 'house' AND number = 'H.R. 1' LIMIT 1;
  IF m_117_h_r_1 IS NULL THEN
    INSERT INTO vr_measures (measure_type, congress, chamber, number, title, short_title, summary, introduced_at, status, source_url, source_label, external_ids)
    VALUES ('bill', 117, 'house', 'H.R. 1', 'For the People Act of 2021', 'For the People Act',
      'Omnibus elections, ethics and campaign-finance bill. Title I requires every state to offer automatic voter registration through motor-vehicle and other designated agencies, same-day registration, and online registration, and restricts voter-roll purges; Title II requires at least fifteen consecutive days of early voting and no-excuse absentee voting with prepaid return postage, and restores voting rights to citizens released from incarceration; Title III sets voting-system security standards including durable paper ballots and risk-limiting audits. Later titles cover redistricting commissions, small-donor public financing and ethics. Passed the House 220-210 on 2021-03-03; the Senate''s companion S. 2093 never cleared cloture.',
      DATE '2021-01-04', 'passed_house', 'https://www.congress.gov/bill/117th-congress/house-bill/1', 'Congress.gov', '{"congressGovId":"hr1-117","billStatus":"https://www.govinfo.gov/bulkdata/BILLSTATUS/117/hr/BILLSTATUS-117hr1.xml"}'::jsonb)
    RETURNING id INTO m_117_h_r_1;
  END IF;

  -- H.R. 4 (117th house) — John R. Lewis Voting Rights Advancement Act of 2021
  SELECT id INTO m_117_h_r_4 FROM vr_measures
   WHERE congress = 117 AND chamber = 'house' AND number = 'H.R. 4' LIMIT 1;
  IF m_117_h_r_4 IS NULL THEN
    INSERT INTO vr_measures (measure_type, congress, chamber, number, title, short_title, summary, introduced_at, status, source_url, source_label, external_ids)
    VALUES ('bill', 117, 'house', 'H.R. 4', 'John R. Lewis Voting Rights Advancement Act of 2021', 'John R. Lewis Voting Rights Advancement Act',
      'Restores the Voting Rights Act preclearance regime struck down in Shelby County v. Holder with a new rolling twenty-five-year coverage formula, and adds a practice-based review list subjecting specific changes — new documentary or photo-ID requirements, polling-place closures and consolidations, redistricting in jurisdictions with recent minority population growth, and voter-roll purges — to federal review before they take effect. Also restores a private right of action and lowers the standard for preliminary relief. Passed the House 219-212 on 2021-08-24; the Senate never voted on it as a standalone bill.',
      DATE '2021-08-17', 'passed_house', 'https://www.congress.gov/bill/117th-congress/house-bill/4', 'Congress.gov', '{"congressGovId":"hr4-117","billStatus":"https://www.govinfo.gov/bulkdata/BILLSTATUS/117/hr/BILLSTATUS-117hr4.xml"}'::jsonb)
