      DATE '2024-05-07', 'passed_house', 'https://www.congress.gov/bill/118th-congress/house-bill/8281', 'Congress.gov', '{"congressGovId":"hr8281-118","billStatus":"https://www.govinfo.gov/bulkdata/BILLSTATUS/118/hr/BILLSTATUS-118hr8281.xml"}'::jsonb)
