  ON CONFLICT (rollcall_id, politician_id) DO NOTHING;

  -- ── issue mappings ────────────────────────────────────────────────────────
  -- Curated in db/vr-issue-seed.json, with the provision-level rationale on every row.
  -- On H.R. 22 only election_security is written. Its election_integrity, voter_id and
  -- voting_access mappings were decided by an earlier pass and are left exactly as they
  -- are — this pass adds a facet to that measure, it does not restate or re-file the rest.
  -- H.R. 1 (117th) — voting_access yea_supports
  INSERT INTO vr_measure_issues (measure_id, issue_key, weight, is_primary, support_meaning, rationale, source_url) VALUES
    (m_117_h_r_1, 'voting_access', 100, true, 'yea_supports',
      'For the People Act of 2021. Title I requires every state to offer automatic voter registration through motor-vehicle and other designated agencies, same-day registration and online registration, and restricts voter-roll purges; Title II requires at least fifteen consecutive days of early voting and no-excuse absentee voting with prepaid return postage, and restores voting rights to citizens released from incarceration. Every one of those provisions widens a registration or casting pathway, so a yea is a vote to expand access. The bill''s election-security title is deliberately NOT mapped: it mandates durable paper ballots and risk-limiting audits while the same bill permits a sworn statement in lieu of documentary ID and restricts list maintenance, so one yea covers both directions of the safeguard facet and records neither.',
      'https://www.congress.gov/bill/117th-congress/house-bill/1')
  ON CONFLICT (measure_id, issue_key) DO NOTHING;

  -- H.R. 4 (117th) — voting_access yea_supports
  INSERT INTO vr_measure_issues (measure_id, issue_key, weight, is_primary, support_meaning, rationale, source_url) VALUES
    (m_117_h_r_4, 'voting_access', 100, true, 'yea_supports',
      'John R. Lewis Voting Rights Advancement Act of 2021. Restores the Voting Rights Act preclearance regime with a rolling twenty-five-year coverage formula and adds a practice-based review list that gates specific access-narrowing changes — new documentary or photo-ID requirements, polling-place closures and consolidations, and voter-roll purges — behind federal review before they take effect, and restores a private right of action. The bill adds no verification requirement, ballot-handling rule or audit provision of its own, so it is mapped to the access facet only; mapping it to election_security would score members on a question the text does not ask.',
      'https://www.congress.gov/bill/117th-congress/house-bill/4')
  ON CONFLICT (measure_id, issue_key) DO NOTHING;

  -- H.R. 5746 (117th) — voting_access yea_supports
  INSERT INTO vr_measure_issues (measure_id, issue_key, weight, is_primary, support_meaning, rationale, source_url) VALUES
    (m_117_h_r_5746, 'voting_access', 100, true, 'yea_supports',
      'Freedom to Vote: John R. Lewis Act, moved as a House amendment to the Senate amendment to H.R. 5746 — a shell bill whose Clerk vote description still reads ''NASA Enhanced Use Leasing Extension Act of 2021'', so the roll is identified by citation and question rather than title. Requires automatic and same-day registration, a minimum of two weeks of early voting including weekends, no-excuse mail voting with ballot tracking and a minimum number of drop boxes per jurisdiction, and makes Election Day a public holiday. A yea is a vote to expand access. Its election-security title is not mapped, for the same internal-split reason as H.R. 1, whose text it incorporates.',
      'https://www.congress.gov/bill/117th-congress/house-bill/5746')
  ON CONFLICT (measure_id, issue_key) DO NOTHING;

  -- H.R. 192 (118th) — election_security yea_supports, voting_access yea_opposes
  INSERT INTO vr_measure_issues (measure_id, issue_key, weight, is_primary, support_meaning, rationale, source_url) VALUES
    (m_118_h_r_192, 'election_security', 100, true, 'yea_supports',
      'Same text as H.R. 884 in the 119th Congress: amends the District of Columbia Home Rule Act to bar non-citizens from voting in District elections. A yea is a vote for citizenship verification as a condition of voting. Same Home Rule Act confound — a nay may be a home-rule position rather than a position on non-citizen voting — and it is recorded here for the same reason.',
      'https://www.congress.gov/bill/118th-congress/house-bill/192'),
    (m_118_h_r_192, 'voting_access', 60, false, 'yea_opposes',
      'Removes a casting pathway created by District law; a yea narrows who may cast a ballot. Same Home Rule Act confound as above.',
      'https://www.congress.gov/bill/118th-congress/house-bill/192')
  ON CONFLICT (measure_id, issue_key) DO NOTHING;

  -- H.R. 8281 (118th) — election_security yea_supports, voting_access yea_opposes
  INSERT INTO vr_measure_issues (measure_id, issue_key, weight, is_primary, support_meaning, rationale, source_url) VALUES
    (m_118_h_r_8281, 'election_security', 100, true, 'yea_supports',
      'SAVE Act, 118th Congress. Amends the National Voter Registration Act to require documentary proof of United States citizenship before a state may register an applicant for a federal election, requires states to establish a program to identify and remove non-citizens from existing rolls using federal immigration and Social Security databases, and creates criminal penalties for officials who register an applicant without the documentation. Eligibility verification and roll maintenance are both squarely in the safeguard facet, so a yea is a vote for tighter verification.',
      'https://www.congress.gov/bill/118th-congress/house-bill/8281'),
    (m_118_h_r_8281, 'voting_access', 70, false, 'yea_opposes',
      'The documentary requirement must be satisfied in person at a registration office, which as a practical matter closes registration by mail and online to any applicant who cannot present documents there, and the acceptable-document list does not accommodate a citizen whose current legal name differs from the name on their birth certificate. The bill adds a barrier at the registration step, so a yea is a vote against easier registration. This is the opposite direction from the same measure''s election_security row on purpose: the two facets are scored independently and this bill genuinely pulls them apart.',
      'https://www.congress.gov/bill/118th-congress/house-bill/8281')
  ON CONFLICT (measure_id, issue_key) DO NOTHING;

  -- H.R. 22 (119th) — election_security yea_supports
  INSERT INTO vr_measure_issues (measure_id, issue_key, weight, is_primary, support_meaning, rationale, source_url) VALUES
    (m_119_h_r_22, 'election_security', 100, false, 'yea_supports',
      'Requires documentary proof of United States citizenship — a passport, a REAL ID showing citizenship, or a birth certificate presented with photo ID — before a state may register an applicant for a federal election, requires states to run a removal program against federal databases for non-citizens already on the rolls, and creates criminal penalties for officials who register an applicant without the documentation. Eligibility verification is the core of the safeguard facet, so a yea is a vote for tighter verification. Not marked primary only because election_integrity already holds that flag on this measure from an earlier pass and moving it would change a published mapping rather than add one.',
      'https://www.congress.gov/bill/119th-congress/house-bill/22')
  ON CONFLICT (measure_id, issue_key) DO NOTHING;

  -- H.R. 884 (119th) — election_security yea_supports, voting_access yea_opposes
  INSERT INTO vr_measure_issues (measure_id, issue_key, weight, is_primary, support_meaning, rationale, source_url) VALUES
    (m_119_h_r_884, 'election_security', 100, true, 'yea_supports',
      'Amends the District of Columbia Home Rule Act to bar any individual who is not a United States citizen from voting in a District election, repealing the effect of the Local Resident Voting Rights Amendment Act of 2022. Citizenship as a condition of casting a ballot is an eligibility safeguard, so a yea is a vote for tighter verification of who may vote. Confound recorded rather than hidden: because the vehicle amends the Home Rule Act, a nay may express opposition to Congress overriding a local District enactment rather than support for non-citizen voting. The mapping is made on the operative election provision and no member''s reason is inferred from the vote.',
      'https://www.congress.gov/bill/119th-congress/house-bill/884'),
    (m_119_h_r_884, 'voting_access', 60, false, 'yea_opposes',
      'Removes an existing casting pathway: non-citizen District residents who registered under the 2022 local law lose the ability to vote in municipal elections. A yea narrows who may cast a ballot. Same Home Rule Act confound as the election_security row above.',
      'https://www.congress.gov/bill/119th-congress/house-bill/884')
  ON CONFLICT (measure_id, issue_key) DO NOTHING;

END $$;

-- ---------------------------------------------------------------------------
-- Verification
-- ---------------------------------------------------------------------------
-- Read-only, and scoped by tuple to exactly this pass's roll calls and measures so it
-- can only ever fail on data this migration is responsible for. A global count would
-- drag in voting_access rows from earlier passes and stop meaning anything.
--
-- The orphan check is narrower still — only the 6 roll calls created here, not house
-- 119/1 roll 102. That roll was ingested earlier through a wider attribution path and 25
-- of its live rows legitimately carry slugs db/vr-member-map.json does not hold. A check
-- that fails on somebody else's correct data is a false alarm, not a guard.
-- ---------------------------------------------------------------------------
DO $$
DECLARE
  n_rolls integer;
  n_votes integer;
  n_orphan integer;
  n_sec integer;
  n_acc integer;
BEGIN
  WITH want (chamber, congress, session, roll_number) AS (VALUES
    ('house'::text, 117::integer, 1::integer, 62::integer),
    ('house'::text, 117::integer, 1::integer, 260::integer),
    ('house'::text, 117::integer, 2::integer, 9::integer),
    ('house'::text, 118::integer, 2::integer, 232::integer),
    ('house'::text, 118::integer, 2::integer, 345::integer),
    ('house'::text, 119::integer, 1::integer, 102::integer),
    ('house'::text, 119::integer, 1::integer, 163::integer)
  ), roll_ids AS (
    SELECT r.id FROM vr_rollcalls r JOIN want w
      ON r.chamber = w.chamber AND r.congress = w.congress
     AND r.session = w.session AND r.roll_number = w.roll_number
  ), fresh (chamber, congress, session, roll_number) AS (VALUES
    ('house'::text, 117::integer, 1::integer, 62::integer),
    ('house'::text, 117::integer, 1::integer, 260::integer),
    ('house'::text, 117::integer, 2::integer, 9::integer),
    ('house'::text, 118::integer, 2::integer, 232::integer),
    ('house'::text, 118::integer, 2::integer, 345::integer),
    ('house'::text, 119::integer, 1::integer, 163::integer)
  ), fresh_ids AS (
    SELECT r.id FROM vr_rollcalls r JOIN fresh f
      ON r.chamber = f.chamber AND r.congress = f.congress
     AND r.session = f.session AND r.roll_number = f.roll_number
  ), mine (congress, chamber, number) AS (VALUES
    (117::integer, 'house'::text, 'H.R. 1'::text),
    (117::integer, 'house'::text, 'H.R. 4'::text),
    (117::integer, 'house'::text, 'H.R. 5746'::text),
    (118::integer, 'house'::text, 'H.R. 192'::text),
    (118::integer, 'house'::text, 'H.R. 8281'::text),
    (119::integer, 'house'::text, 'H.R. 22'::text),
    (119::integer, 'house'::text, 'H.R. 884'::text)
  ), measure_ids AS (
    SELECT m.id FROM vr_measures m JOIN mine k
      ON m.congress = k.congress AND m.chamber = k.chamber AND m.number = k.number
  )
  SELECT (SELECT count(*) FROM roll_ids),
         (SELECT count(*) FROM vr_member_votes v WHERE v.rollcall_id IN (SELECT id FROM roll_ids)),
         (SELECT count(*) FROM vr_member_votes v WHERE v.rollcall_id IN (SELECT id FROM fresh_ids)
            AND v.politician_id NOT IN (
              'adam_smith', 'andy_kim', 'aoc', 'barrasso', 'bennie_thompson', 'bmoore', 'boebert', 'booker', 'brian_mast', 'britt', 'bruce_westerman', 'chris_murphy', 'collins', 'crockett', 'cruz', 'cstewart', 'curtis', 'dan_goldman', 'don_bacon', 'don_davis', 'durbin', 'emmer', 'ernst', 'fetterman', 'frank_lucas', 'french_hill', 'gaetz', 'gallego', 'graham', 'grassley', 'greg_landsman', 'haley_stevens', 'hawley', 'jake_auchincloss', 'jason_smith', 'jayapal', 'jeffries', 'jim_jordan', 'john_cornyn', 'jon_ossoff', 'josh_brecheen', 'josh_gottheimer', 'julie_fedorchak', 'kaine', 'kclark', 'kennedy', 'kennedy_john', 'khanna', 'lankford', 'lee', 'mariannette_miller_meeks', 'mark_kelly', 'massie', 'maxine_waters', 'mcconnell', 'meeks', 'michael_guest', 'mike_collins', 'mike_ezell', 'mike_flood', 'mike_johnson', 'mike_lawler', 'mike_simpson', 'mike_waltz', 'mtg', 'murkowski', 'omar', 'owens', 'rand_paul', 'reed', 'rick_crawford', 'risch', 'rob_bresnahan', 'rosen', 'rubio', 'ryan_mackenzie', 'sanders', 'scalise', 'schiff', 'schumer', 'scott_perry', 'shaheen', 'slotkin', 'stefanik', 'steny_hoyer', 'stephanie_bice', 'steve_womack', 'summer_lee', 'tgabbard', 'thune', 'tim_scott', 'tlaib', 'tom_cole', 'tom_suozzi', 'torres', 'trent_kelly', 'troy_downing', 'van_hollen', 'warnock', 'warren', 'zeldin'
            )),
         (SELECT count(*) FROM vr_measure_issues i WHERE i.issue_key = 'election_security'
            AND i.measure_id IN (SELECT id FROM measure_ids)),
         (SELECT count(*) FROM vr_measure_issues i WHERE i.issue_key = 'voting_access'
            AND i.measure_id IN (SELECT id FROM measure_ids))
    INTO n_rolls, n_votes, n_orphan, n_sec, n_acc;

  RAISE NOTICE 'Election facets: % roll calls, % member votes, % election_security and % voting_access mappings', n_rolls, n_votes, n_sec, n_acc;

  IF n_rolls <> 7 THEN
    RAISE EXCEPTION 'Election facets: expected 7 roll calls, found %', n_rolls;
  END IF;
  IF n_votes < 385 THEN
    RAISE EXCEPTION 'Election facets: expected at least 385 member votes on these roll calls, found %', n_votes;
  END IF;
  IF n_orphan > 0 THEN
    RAISE EXCEPTION 'Election facets: % member vote(s) on the roll calls this migration creates carry a politician_id outside db/vr-member-map.json', n_orphan;
  END IF;
  IF n_sec <> 4 THEN
    RAISE EXCEPTION 'Election facets: expected 4 election_security mappings on this pass''s measures, found %', n_sec;
  END IF;
  IF n_acc <> 7 THEN
    RAISE EXCEPTION 'Election facets: expected 7 voting_access mappings on this pass''s measures, found %', n_acc;
  END IF;
END $$;
